{
  "project_id": "bae368e653014413b3f2",
  "name": "saas_foundation",
  "query": "create schema if not exists private;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  avatar_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 120),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.organization_members (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null default 'member' check (role in ('owner', 'admin', 'member')),
  created_at timestamptz not null default now(),
  primary key (organization_id, user_id)
);

create table public.projects (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  slug text not null check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, slug)
);

create index organization_members_user_id_idx on public.organization_members(user_id);
create index projects_organization_id_idx on public.projects(organization_id);

create or replace function private.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger profiles_set_updated_at before update on public.profiles
for each row execute function private.set_updated_at();
create trigger organizations_set_updated_at before update on public.organizations
for each row execute function private.set_updated_at();
create trigger projects_set_updated_at before update on public.projects
for each row execute function private.set_updated_at();

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'))
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function private.handle_new_user();

create or replace function private.add_organization_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.organization_members (organization_id, user_id, role)
  values (new.id, new.created_by, 'owner');
  return new;
end;
$$;

create trigger organizations_add_owner
after insert on public.organizations
for each row execute function private.add_organization_owner();

create or replace function private.org_role(target_org uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.organization_members
  where organization_id = target_org and user_id = (select auth.uid());
$$;

create or replace function private.is_org_member(target_org uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.organization_members
    where organization_id = target_org and user_id = (select auth.uid())
  );
$$;

revoke execute on function private.org_role(uuid) from public;
revoke execute on function private.is_org_member(uuid) from public;
grant execute on function private.org_role(uuid) to authenticated;
grant execute on function private.is_org_member(uuid) to authenticated;

alter table public.profiles enable row level security;
alter table public.organizations enable row level security;
alter table public.organization_members enable row level security;
alter table public.projects enable row level security;

create policy "profiles_select_own" on public.profiles for select to authenticated
using ((select auth.uid()) = id);
create policy "profiles_update_own" on public.profiles for update to authenticated
using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

create policy "organizations_select_members" on public.organizations for select to authenticated
using (private.is_org_member(id));
create policy "organizations_insert_own" on public.organizations for insert to authenticated
with check ((select auth.uid()) = created_by);
create policy "organizations_update_admins" on public.organizations for update to authenticated
using (private.org_role(id) in ('owner', 'admin'))
with check (private.org_role(id) in ('owner', 'admin'));
create policy "organizations_delete_owner" on public.organizations for delete to authenticated
using (private.org_role(id) = 'owner');

create policy "members_select_members" on public.organization_members for select to authenticated
using (private.is_org_member(organization_id));
create policy "members_insert_self" on public.organization_members for insert to authenticated
with check (user_id = (select auth.uid()) and private.is_org_member(organization_id));
create policy "members_update_admins" on public.organization_members for update to authenticated
using (private.org_role(organization_id) in ('owner', 'admin'))
with check (private.org_role(organization_id) in ('owner', 'admin'));
create policy "members_delete_admins" on public.organization_members for delete to authenticated
using (private.org_role(organization_id) in ('owner', 'admin') and role <> 'owner');

create policy "projects_select_members" on public.projects for select to authenticated
using (private.is_org_member(organization_id));
create policy "projects_insert_admins" on public.projects for insert to authenticated
with check (private.org_role(organization_id) in ('owner', 'admin') and created_by = (select auth.uid()));
create policy "projects_update_admins" on public.projects for update to authenticated
using (private.org_role(organization_id) in ('owner', 'admin'))
with check (private.org_role(organization_id) in ('owner', 'admin'));
create policy "projects_delete_admins" on public.projects for delete to authenticated
using (private.org_role(organization_id) in ('owner', 'admin'));

comment on schema private is 'Internal helper functions; not exposed through the Data API';
comment on table public.organizations is 'Tenant organizations for the SaaS application';
comment on table public.organization_members is 'Users and roles within each tenant organization';
comment on table public.projects is 'Example organization-scoped SaaS resource';"
}

