{
  "project_id": "bae368e653014413b3f2",
  "name": "tighten_membership_access",
  "query": "drop policy "members_insert_self" on public.organization_members;
create policy "members_insert_admins" on public.organization_members for insert to authenticated
with check (
  private.org_role(organization_id) in ('owner', 'admin')
  and role in ('admin', 'member')
);

 drop policy "members_update_admins" on public.organization_members;
create policy "members_update_admins" on public.organization_members for update to authenticated
using (private.org_role(organization_id) in ('owner', 'admin'))
with check (
  private.org_role(organization_id) in ('owner', 'admin')
  and (role <> 'owner' or private.org_role(organization_id) = 'owner')
);

grant select, insert, update, delete on public.profiles to authenticated;
grant select, insert, update, delete on public.organizations to authenticated;
grant select, insert, update, delete on public.organization_members to authenticated;
grant select, insert, update, delete on public.projects to authenticated;"
}

